using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using ParkingLotEnvironment.Training;
namespace ParkingLotEnvironment.CloudPilot {public static class PorterReferenceBuilder {
 public const string W="Assets/ParkingLotEnvironment/CloudPilot/PorterReference20261105";
 [Serializable]class Record{public string name,file;public int vertexCount,indexCount,material;}
 [Serializable]class Model{public Record[] meshes;}
 static Material Mat(string name,Color color,float metallic,float smooth,string shader="Standard"){var m=new Material(Shader.Find(shader)){name=name,color=color};if(m.HasProperty("_Metallic"))m.SetFloat("_Metallic",metallic);if(m.HasProperty("_Glossiness"))m.SetFloat("_Glossiness",smooth);AssetDatabase.CreateAsset(m,W+"/"+name+".mat");return m;}
 public static void Apply(GameObject root,string output){var layout=root.GetComponentInChildren<ParkingTrainingLayout>();var parked=layout.transform.Find("Parked_T_4_PortedModel");var car=parked.Find("Hyundai_Porter_II_max7th");var data=JsonUtility.FromJson<Model>(File.ReadAllText(W+"/PorterData/porter.json"));var mats=new Dictionary<string,Material>();
  mats["BluePaint"]=Mat("Porter_DeepBlue_PhotoReference",new Color(.125f,.185f,.265f),.10f,.48f);
  mats["Glass"]=Mat("Porter_RealGlazing",new Color(.025f,.034f,.040f,.36f),0,.94f,"ParkingLot/PorterReference20261105/Glass");
  mats["Rubber"]=Mat("Porter_WorkTire",new Color(.045f,.049f,.052f),0,.13f);
  mats["Steel"]=Mat("Porter_SatinWheel",new Color(.34f,.36f,.38f),.63f,.36f);
  mats["DarkTrim"]=Mat("Porter_BlackTrim",new Color(.037f,.042f,.045f),0,.23f);
  mats["Headlight"]=Mat("Porter_ClearReflector",new Color(.5f,.52f,.54f),.7f,.82f,"ParkingLot/PorterReference20261105/Headlamp");
  foreach(var item in data.meshes){var mesh=new Mesh{name="PorterReference_"+item.name,indexFormat=IndexFormat.UInt32};var vv=new Vector3[item.vertexCount];var nn=new Vector3[item.vertexCount];var uv=new Vector2[item.vertexCount];var indices=new int[item.indexCount];using(var r=new BinaryReader(File.OpenRead(W+"/PorterData/"+item.file))){for(int i=0;i<vv.Length;i++){vv[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());nn[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());uv[i]=new Vector2(r.ReadSingle(),r.ReadSingle());}for(int i=0;i<indices.Length;i++)indices[i]=(int)r.ReadUInt32();}mesh.vertices=vv;mesh.normals=nn;mesh.uv=uv;mesh.triangles=indices;mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,W+"/"+mesh.name+".asset");var part=car.Find(item.name);part.GetComponent<MeshFilter>().sharedMesh=mesh;part.GetComponent<MeshRenderer>().sharedMaterial=mats[item.name];}
  var fabric=Mat("Porter_SeatFabric",new Color(.13f,.15f,.16f),0,.19f);var interior=Mat("Porter_Dashboard",new Color(.045f,.055f,.06f),0,.23f);var inside=new GameObject("PhotoReference_InteriorAndWipers").transform;inside.SetParent(car,false);
  Box(inside,"CabinFloor",new Vector3(0,.60f,1.03f),new Vector3(1.54f,.08f,1.32f),interior);Box(inside,"CabRearLiner",new Vector3(0,.98f,.42f),new Vector3(1.55f,.95f,.055f),fabric);Box(inside,"Dashboard",new Vector3(0,1.07f,1.93f),new Vector3(1.50f,.20f,.30f),interior);
  foreach(float x in new[]{-.50f,0f,.50f}){Box(inside,"SeatBase",new Vector3(x,.81f,1.09f),new Vector3(.43f,.17f,.49f),fabric);var back=Box(inside,"SeatBack",new Vector3(x,1.13f,.85f),new Vector3(.43f,.60f,.13f),fabric);back.transform.localRotation=Quaternion.Euler(-8,0,0);Box(inside,"HeadRest",new Vector3(x,1.49f,.84f),new Vector3(.24f,.18f,.11f),fabric);}
  foreach(float x in new[]{-.39f,.39f}){var blade=Box(inside,"WindshieldWiper",new Vector3(x,1.265f,2.211f),new Vector3(.53f,.017f,.022f),mats["DarkTrim"]);blade.transform.localRotation=Quaternion.Euler(0,0,x<0?4:-4);}
  SteeringWheel(inside,interior);foreach(Transform t in inside){var r=t.GetComponent<Renderer>();if(r){r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.ReflectionProbeStatic);}}
  foreach(var p in car.GetComponentsInChildren<Renderer>()){p.lightmapIndex=-1;p.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;}
  var b=ContextBuilder.BoundsOf(parked.gameObject);parked.position+=new Vector3(0,.005f-b.min.y,0);b=ContextBuilder.BoundsOf(parked.gameObject);var box=parked.GetComponent<BoxCollider>();if(box){box.center=parked.InverseTransformPoint(b.center);box.size=new Vector3(b.size.z,b.size.y,b.size.x);}
  var obstacle=layout.obstacles.Single(o=>o.id==parked.name);obstacle.center=b.center;obstacle.size=b.size;layout.truckModelNote="Photo-referenced Porter II derivative: official diesel supercab 5100/5155 x1740 x1970mm; 2640mm wheelbase. STL by max7th CC BY4.0; independently modeled interior/optics, not a scan.";
  var canonical=new GameObject("HyundaiPorterII_PhotoReferenced");var clone=UnityEngine.Object.Instantiate(parked.gameObject,canonical.transform);clone.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z);clone.transform.RotateAround(Vector3.zero,Vector3.up,-90);PrefabUtility.SaveAsPrefabAsset(canonical,W+"/HyundaiPorterII_PhotoReferenced.prefab");UnityEngine.Object.DestroyImmediate(canonical);
  File.WriteAllText(output+"/porter-changes.txt","Official photo/dimension reference: https://www.hyundai.com/content/dam/hyundai/kr/ko/data/vehicles/catalog/porter2-catalog.pdf\nDeep desaturated blue; crease-preserving weighted normals; headboard height corrected; roof 1.970m; front/rear tire diameters .654/.562m; wheelbase2.640m; front wheel aligned with arch center. New actual cabin interior, glazing, wipers and three-section optical reflector appearance. Existing parking context/lighting/other vehicles untouched.\nBounds: "+b+"\nSTL source attribution: PorterData/CREDITS.txt\nNot trained ML, not a scan; photo-referenced modeling.\n");AssetDatabase.SaveAssets();
 }
 static GameObject Box(Transform p,string n,Vector3 pos,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=pos;g.transform.localScale=size;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=m;return g;}
 static void SteeringWheel(Transform p,Material m){var mesh=new Mesh{name="Porter_SteeringWheel"};var v=new List<Vector3>();var ix=new List<int>();int a=40,b=8;for(int i=0;i<a;i++)for(int j=0;j<b;j++){float x=i*Mathf.PI*2/a,y=j*Mathf.PI*2/b;v.Add(new Vector3(Mathf.Cos(x)*(.175f+.013f*Mathf.Cos(y)),Mathf.Sin(x)*(.175f+.013f*Mathf.Cos(y)),.013f*Mathf.Sin(y)));}for(int i=0;i<a;i++)for(int j=0;j<b;j++){int k=i*b+j,l=((i+1)%a)*b+j,n=i*b+(j+1)%b,o=((i+1)%a)*b+(j+1)%b;ix.AddRange(new[]{k,l,n,l,o,n});}mesh.SetVertices(v);mesh.SetTriangles(ix,0);mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,W+"/PorterSteeringWheel.asset");var g=new GameObject("SteeringWheel");g.transform.SetParent(p,false);g.transform.localPosition=new Vector3(-.49f,1.12f,1.70f);g.transform.localRotation=Quaternion.Euler(35,0,0);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=m;}
}}
